parent = [0, 1, 2, 3, 4, 5]
size = [1, 1, 1, 1, 1, 1]

def find(x):
    root = x
    while parent[root] != root:
        root = parent[root]
    while parent[x] != root:
        nxt = parent[x]
        parent[x] = root
        x = nxt
    return root

def union(a, b):
    ra = find(a)
    rb = find(b)
    if ra == rb:
        return
    if size[ra] < size[rb]:
        ra, rb = rb, ra
    parent[rb] = ra
    size[ra] += size[rb]

for a, b in [(0, 1), (2, 3), (3, 4)]:
    union(a, b)

